22	const PROCESSING_FEE = 5;
23	
24	// Binary floating point makes exact multiples land a hair off (100 * 1.1 + 5 =
25	// 115.00000000000001); snap to cent precision so only genuine fractions round up.
26	const roundUpInMHPCOsFavour = (amount: number): number =>
27	  Math.ceil(Number(amount.toFixed(6)));
28	
29	const SWORD_BASE_PREMIUM = 100;
30	const FIRST_INSURANCE_SURCHARGE = 0.1;
31	
32	const quote = (step: QuoteStep): number => {
33	  const basePremium = step.items.length === 0 ? 0 : SWORD_BASE_PREMIUM;
34	
35	  return roundUpInMHPCOsFavour(basePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
36	};
37	
38	export const runScenario = (scenario: Scenario): ScenarioResults => {
39	  return { results: scenario.steps.map((step) => ({ premium: quote(step) })) };
40	};
