const basePremiumOf = (_item: Item): number => SWORD_BASE_PREMIUM;

const quote = (step: QuoteStep): number => {
  const basePremium = sum(step.items.map(basePremiumOf));

  return roundUpInMHPCOsFavour(basePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
};

const sum = (amounts: number[]): number =>
  amounts.reduce((total, amount) => total + amount, 0);

const PROCESSING_FEE = 5;
